// A synthesizable configurable divider

// NOTE: Generated by ChatGPT, because lazy
module pll_mod_divider #(
    parameter W = 8,
    // Power-on divisor.  Runtime SET_DIV/LOAD_DIV may still override it, but
    // the generator binds a deterministic out_div here instead of relying on
    // the divider's old hard-coded /2 reset value.
    parameter integer DIV_INIT = 2
)(
    input  wire             clk,
    input  wire             rst_n,     // active low reset
    input  wire [W-1:0]     set_div,   // new division value (>=1)
    input  wire             load_div,  // pulse to latch set_div into active divisor (synchronous)
    output wire             out        // divided clock output (/1 bypass)
);

    // active divisor
    reg [W-1:0] div;
    // counters and limits for alternating high/low when odd
    reg [W-1:0] cnt;
    reg [W-1:0] high_count, low_count;
    reg        high_phase; // 1 => currently producing high phase (counting high_count)
    reg        out_reg;

    // A true /1 output is a bypass, not a toggle.  This keeps OUT_DIV equal
    // to the DCO output when the specification requests out_div=1.
    assign out = (div == 1) ? clk : out_reg;

    // compute counts when div changes (synchronous)
    // high_count = ceil(div/2), low_count = floor(div/2)
    wire [W-1:0] half = div >> 1;
    wire        div_is_odd = div[0];

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            div        <= (DIV_INIT < 1) ? 1 : DIV_INIT;
            cnt        <= 0;
            out_reg    <= 0;
            high_phase <= 1'b0;
            high_count <= 1;
            low_count  <= 1;
        end else begin
            // update divisor synchronously on load_div
            if (load_div) begin
                // /1 is handled by the bypass mux above.  Reject zero.
                div <= (set_div < 1) ? 1 : set_div;
            end

            // recompute high/low counts when div changes
            // ensure at least 1
            if (div == 1) begin
                high_count <= 1;
                low_count  <= 1;
            end else if (div_is_odd) begin
                // odd: e.g., div=5 -> high=3, low=2
                high_count <= half + 1;
                low_count  <= half;
            end else begin
                // even: div=6 -> high=3 low=3
                high_count <= half;
                low_count  <= half;
            end

            // counting / toggling
            if (div == 1) begin
                // divide by 1: the bypass mux above makes out follow clk.
                cnt <= 0;
            end else begin
                // normal operation: count cycles within current phase
                if (cnt + 1 >= (high_phase ? high_count : low_count)) begin
                    // phase complete -> toggle output and start next phase
                    out_reg <= ~out_reg;
                    cnt <= 0;
                    high_phase <= ~high_phase;
                end else begin
                    cnt <= cnt + 1;
                end
            end
        end
    end

endmodule
